"""Step 144 (#34) Maya option windows of the Deform menu: same spec as operators/option_windows.py (``F`` fields,
``Window`` = one ``allset.opt_<key>`` operator; option_windows._extend appends ``WINDOWS``).

Titles, buttons, Basic tab fields in screen order and factory defaults: Maya's Deform
option windows. Every Python-built deformer box also has an
Advanced tab (Deformation order / Exclusive / Partition): Blender's modifier stack
has none of them, so they and every Basic field Blender can't honour are listed as ``missing``, never faked.
The deformers themselves: operators/deformers.py.
"""
from ..i18n import source_message as _dcc_source, display_message as _dcc_display, format_message as _dcc_format
from ..i18n import tr as _zh, enum_items as _zh_enum, native as _zh_native
import bpy
from bpy.props import IntVectorProperty
from .option_windows import F, Window
from .option_windows_modify import FString

class FDivisions(F):
    """Maya's three-int field (Lattice Divisions S T U)."""

    def __init__(self, name, label, default):
        super().__init__(name, label, 'vec3int', default)

    def prop(self):
        return IntVectorProperty(name=_zh_native(self.label.rstrip(':'), 'MWK:operators/option_windows_deform.py:28'), default=self.default, size=3, min=2, soft_max=50, translation_context='MWK:operators/option_windows_deform.py:28')
ADVANCED = (_dcc_source('Deformation order (Advanced tab; the modifier stack order)'), _dcc_source('Exclusive / Partition to use / Partition name (Advanced tab)'))
ENVELOPE = _dcc_source('Envelope (the modifier has no strength)')

def _create(kind):

    def run(context, v):
        from . import deformers
        deformers.create(context, kind, v)
        return {'FINISHED'}
    return run

def _cluster(context, v):
    return bpy.ops.allset.cluster('EXEC_DEFAULT', envelope=float(v['envelope']))

def _soft_mod(context, v):
    return bpy.ops.allset.soft_mod('EXEC_DEFAULT', radius=float(v['radius']))

def _match(kind):
    return ('allset.deformer', {'kind': kind})

def _bounds():
    return [F('low', _dcc_source('Low bound:'), 'float', -1.0, lo=-10.0, hi=0.0, translation_context='MWK:operators/option_windows_deform.py:57'), F('high', _dcc_source('High bound:'), 'float', 1.0, lo=0.0, hi=10.0, translation_context='MWK:operators/option_windows_deform.py:58')]

def _wire_edit(action):

    def run(context, v):
        return bpy.ops.allset.wire_edit('EXEC_DEFAULT', action=action, node=v['node'] if v['specify'] else '')
    return run

def _dropoff_locator(context, v):
    return bpy.ops.allset.wire_dropoff_locator('EXEC_DEFAULT', node=v['node'], envelope=float(v['envelope']), percent=float(v['percent']))

def _point_on_curve(context, v):
    return bpy.ops.allset.point_on_curve('EXEC_DEFAULT', weight=float(v['weight']))

